      'cmd.box.es': 'CAJA',
      'cmd.cylinder.desc': 'Crea un sólido cilíndrico por radio de base y altura.',
      'cmd.cylinder.es': 'CILINDRO',
      'cmd.extrude.desc': 'Empuja un perfil 2D cerrado en línea recta para crear un sólido.',
      'cmd.extrude.es': 'EXTRUIR',
      'cmd.revolve.desc': 'Gira un perfil 2D alrededor de un eje para generar un sólido de revolución.',
      'cmd.revolve.es': 'REVOLVER',
      'cmd.sweep.desc': 'Desplaza un perfil a lo largo de una trayectoria curva (tubería, moldura).',
      'cmd.sweep.es': 'BARRIDO',
      'cmd.loft.desc': 'Genera una forma suave conectando dos o más perfiles entre sí (solevación).',
      'cmd.loft.es': 'SOLEVACIÓN',
      'cmd.union.desc': 'Fusiona dos o más sólidos en un solo objeto (unión booleana).',
      'cmd.union.es': 'UNIÓN',
      'cmd.subtract.desc': 'Resta el volumen de un sólido de otro (perforar, recortar volumen).',
      'cmd.subtract.es': 'RESTA',
      'cmd.intersect.desc': 'Conserva únicamente el volumen común entre dos o más sólidos.',
      'cmd.intersect.es': 'INTERSECCIÓN',
      'cmd.3dorbit.desc': 'Órbita libre alrededor del modelo 3D para visualizar desde cualquier ángulo.',
      'cmd.render.desc': 'Genera una imagen renderizada del modelo 3D con materiales, luces y cámara.',
      'cmd.dist.desc': 'Mide la distancia y ángulo entre dos puntos del dibujo.',
      'cmd.list.desc': 'Muestra propiedades detalladas de un objeto seleccionado (capa, tipo, área, longitud).',
      'cmd.area.desc': 'Calcula el área y perímetro de un polígono o selección de puntos.',
      'cmd.measure.desc': 'Coloca puntos o bloques a lo largo de un objeto a intervalos iguales.',
      'cmd.zoom.desc': 'Amplía o reduce la vista del área de dibujo (opciones: E, W, P, All).',
      'cmd.purge.desc': 'Elimina elementos no utilizados del archivo: capas, bloques, estilos, tipos de línea.',
      'cmd.audit.desc': 'Detecta y corrige errores internos del archivo DWG.',
      'cmd.wblock.desc': 'Exporta objetos o el dibujo completo a un archivo DWG separado.',

      /* ---- New commands ---- */
      'cmd.xline.desc': 'Crea una línea infinita en ambas direcciones, ideal como geometría de referencia y alineación.',
      'cmd.ray.desc': 'Crea un rayo: una semilínea infinita que parte de un punto en una dirección definida.',
      'cmd.point.desc': 'Coloca un punto de referencia en el dibujo. Usa PTYPE para definir el estilo visual del punto.',
      'cmd.region.desc': 'Convierte un borde cerrado en una región sólida 2D para operaciones booleanas.',
      'cmd.erase.desc': 'Elimina objetos seleccionados del dibujo. También se puede borrar seleccionando y pulsando Supr.',
      'cmd.align.desc': 'Alinea objetos definiendo puntos de origen y destino. Puede mover, rotar y escalar simultáneamente.',
      'cmd.lengthen.desc': 'Alarga o acorta líneas, arcos y polilíneas con opciones de total, incremento, porcentaje o dinámico.',
      'cmd.breakatpoint.desc': 'Rompe un objeto en dos partes exactamente en el punto seleccionado.',
      'cmd.group.desc': 'Agrupa objetos seleccionados para tratarlos como una unidad temporal y editable.',
      'cmd.snap.desc': 'Configura la adhesión del cursor a puntos de la cuadrícula.',
      'cmd.grid.desc': 'Muestra u oculta la cuadrícula visual de referencia. Es solo visual; no afecta el dibujo.',
      'cmd.dsettings.desc': 'Abre la configuración de dibujo: OSNAP, Polar, Grid, Snap y Dynamic Input.',
      'cmd.layerp.desc': 'Restaura el estado de capas anterior al último cambio. Como Undo pero solo para capas.',
      'cmd.laymatch.desc': 'Cambia la capa de un objeto para que coincida con la de otro objeto de destino.',
      'cmd.laywalk.desc': 'Recorre las capas una por una, mostrando u ocultando su contenido para revisar la organización.',
      'cmd.dimradius.desc': 'Crea una cota de radio para un círculo o arco.',
      'cmd.dimdiameter.desc': 'Crea una cota de diámetro para un círculo o arco, mostrando el símbolo Ø.',
      'cmd.dimangular.desc': 'Crea una cota angular que mide el ángulo entre dos líneas o definido por tres puntos.',
      'cmd.mleader.desc': 'Crea una nota con flecha líder y texto multilínea. Ideal para etiquetas y llamadas.',
      'cmd.tablestyle.desc': 'Crea y administra estilos de tabla: apariencia de encabezados, datos y totales.',
      'cmd.pedit.desc': 'Edita polilíneas: unir segmentos, abrir/cerrar, suavizar, spline o asignar ancho.',
      'cmd.hatchedit.desc': 'Modifica un hatch existente: cambiar patrón, escala, ángulo o boundaries.',
      'cmd.splineedit.desc': 'Edita splines existentes: mover puntos de control, ajustar tangencias o convertir.',
      'cmd.sphere.desc': 'Crea un sólido esférico definido por un centro y un radio.',
      'cmd.cone.desc': 'Crea un cono sólido definido por radio de base y altura.',
      'cmd.wedge.desc': 'Crea un sólido cuña: un prisma triangular recto definido por largo, ancho y alto.',
      'cmd.slice.desc': 'Corta un sólido 3D con un plano, dividiéndolo en dos o más partes.',
      'cmd.presspull.desc': 'Empuja o jala una superficie cerrada para crear o modificar un sólido.',
      'cmd.solidedit.desc': 'Edita caras, aristas y bodies de sólidos 3D: extruir, mover, rotar, cuña o bisel.',
      'cmd.section.desc': 'Crea una región 2D a partir de la intersección de un plano con sólidos 3D.',
      'cmd.pan.desc': 'Desplaza la vista del dibujo sin cambiar el zoom.',
      'cmd.units.desc': 'Configura las unidades de dibujo y la precisión de coordenadas y ángulos.',
      'cmd.regen.desc': 'Regenera todo el dibujo desde la base de datos. Útil cuando los círculos se ven segmentados.',
      'cmd.limits.desc': 'Define los límites del área de dibujo y el rango de coordenadas.',
      'cmd.qselect.desc': 'Selecciona objetos por propiedades: capa, color, tipo, longitud.',

