      'vis.orbit.desc': 'Navega libremente alrededor del modelo 3D para verlo desde cualquier ángulo.',
      'vis.orbit.tip': 'Mantén Shift + botón central del ratón para órbita libre. Escape para salir.',
      'vis.box.desc': 'Crea un sólido rectangular primitivo definido por largo, ancho y alto.',
      'vis.box.tip': 'Es la primitiva 3D más usada. Úsala como base para recortar con SUBTRACT.',
      'vis.sweep.desc': 'Desplaza un perfil 2D a lo largo de una trayectoria curva para crear un sólido.',
      'vis.sweep.tip': 'Ideal para tuberías, molduras, rieles y cualquier forma con sección constante.',
      'vis.orto.title': 'Modo ORTO (F8)',
      'vis.orto.desc': 'Restringe el cursor a movimientos perfectamente horizontales o verticales.',
      'vis.orto.tip': 'Actívalo siempre que dibujes líneas rectas de plano. Alterna con F8.',
      'vis.snap.title': 'Cuadrícula y SNAP',
      'vis.snap.desc': 'La cuadrícula visual ayuda a orientar el dibujo. SNAP engancha el cursor a los puntos de la cuadrícula.',
      'vis.snap.tip': 'GRID solo es visual; SNAP es el que realmente mueve el cursor. Configura el espaciado en Drafting Settings.',
      'vis.plotstyle.title': 'Estilos de trazado (Plot Styles)',
      'vis.plotstyle.desc': 'Controlan cómo se imprime cada capa: grosor de línea, color de impresión y trama.',
      'vis.plotstyle.tip': 'Usa .CTB (por color) para proyectos simples o .STB (por estilo) para control avanzado.',
      'vis.xref.title': 'Referencias externas (Xref)',
      'vis.xref.desc': 'Vincula archivos DWG externos como referencias. Se actualizan automáticamente cuando el archivo original cambia.',
      'vis.xref.tip': 'Ideal para trabajo en equipo: cada profesional actualiza su parte y el plano colectivo se refresca solo.',
      'vis.cui.title': 'Personalización de interfaz (CUI)',
      'vis.cui.desc': 'Modifica barras de herramientas, menús, teclas rápidas y paneles arrastrando comandos.',
      'vis.cui.tip': 'Escribe CUI para abrir el editor. Crea un grupo de comandos personalizados para tu flujo.',
      'vis.purge.title': 'PURGE y AUDIT',
      'vis.purge.desc': 'PURGE elimina capas, bloques y estilos no usados. AUDIT corrige errores internos del DWG.',
      'vis.purge.tip': 'Ejecuta PURGE periódicamente para reducir tamaño. AUDIT después de un cierre inesperado.',
      'vis.cta.eyebrow': '¿Listo para practicar?',
      'vis.cta.title': 'Pon en práctica lo que viste',
      'vis.cta.desc': 'Abre cualquier nivel y busca los comandos que te interesan.',
      'vis.cta.btn': 'Empezar desde cero',

