  'tips.tab.title': 'De longitud a ángulo con TAB (F12)',
  'tips.tab.desc': 'Con el Input Dinámico (F12) activo, al dibujar una LÍNEA escribe la longitud, pulsa TAB y el campo cambia al ángulo: escribe el valor y pulsa Enter. Usa ESC para cancelar y ESC ×3 para cerrar todo.',
