      'tuts.hero.eyebrow': 'Tips &amp; Tutoriales',
      'tuts.hero.title': 'Domina AutoCAD con estos tips',
      'tuts.hero.desc': 'Tutoriales prácticos con ejemplos visuales, comandos esenciales y atajos para cada nivel.',
      'tuts.hero.btn': 'Ver todos',
