      'vis.eyebrow': 'Visual &amp; interactive',
      'vis.title': 'Visual command examples',
      'vis.desc': 'Step-by-step diagrams showing exactly what each command does: before, after, and how to get there.',
      'vis.filter.all': 'All',
      'vis.filter.dibujo': 'Drawing',
      'vis.filter.mod': 'Modification',
      'vis.filter.precision': 'Precision',
      'vis.filter.capas': 'Layers',
      'vis.filter.3d': '3D',
      'vis.badge.2d': '2D',
      'vis.badge.atajos': 'Shortcuts',
