  'tips.tab.title': 'From length to angle with TAB (F12)',
  'tips.tab.desc': 'With Dynamic Input (F12) on, when drawing a LINE type the length, press TAB and the field switches to the angle: type the value and press Enter. Use ESC to cancel and ESC ×3 to close everything.',
  'tips.tab.tip': 'If the dynamic fields do not appear next to the cursor while drawing, press F12 to turn on Dynamic Input.',
  'tips.angle.title': 'Calculate and measure angles',
  'tips.angle.desc': 'To find an angle use MEASUREGEOM (Angle option) or dimension it directly with DIMANGULAR. Use ANGBASE to set the 0° reference and ANGDIR to set the direction of positive angles.',
  'tips.angle.tip': 'Do two lines need to be perpendicular? Measure the angle: it must be exactly 90°.',
