      'tuts.hero.eyebrow': 'Tips &amp; Tutorials',
      'tuts.hero.title': 'Master AutoCAD with these tips',
      'tuts.hero.desc': 'Practical tutorials with visual examples, essential commands and shortcuts for every level.',
      'tuts.hero.btn': 'See all',
      'tuts.filter.all': 'All',
      'tuts.filter.geometria': 'Geometry',
